package org.jlinalg.cli;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.jlinalg.sequence.FastaIndexes;
import static org.junit.jupiter.api.Assertions.*;
import static org.jlinalg.cli.SeuratDifferentialContracts.*;

class SpliceAiToolsTest {
    @TempDir Path temporary;
    static final String HEADER="##fileformat=VCFv4.2\n##INFO=<ID=SpliceAI,Number=.,Type=String,Description=\"Format: ALLELE|SYMBOL|DS_AG|DS_AL|DS_DG|DS_DL|DP_AG|DP_AL|DP_DG|DP_DL\">\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\n";
    private int run(String...args){return SpliceAiToolsCli.run(args,new PrintStream(new ByteArrayOutputStream()),new PrintStream(new ByteArrayOutputStream()));}
    private int execute(Map<String,Object> r)throws IOException{Path request=temporary.resolve("request.json");json(request,r);return run("--request",request.toString());}
    private Map<String,Object> request()throws IOException{Files.writeString(temporary.resolve("annotated.vcf"),HEADER+"1\t8\tliteral α\tA\tC,G\t.\t.\tSpliceAI=C|gene.1|0.00|-0.00|0.23|-0.02|0|-2|4|1,C|gene.1|.|.|.|.|.|.|.|.,G|other|NaN|0.2|0|Inf|0|1|2|3\n");return new LinkedHashMap<>(Map.of("schema_version",1,"mode","RUN","backend","NATIVE","out","result","annotated_vcf","annotated.vcf"));}
    @Test void nativeImportRetainsAllContextsAndMissingNonfiniteSignedZero()throws Exception{assertEquals(0,execute(request()));Path root=temporary.resolve("result");String annotations=Files.readString(root.resolve("results/native/annotations.tsv"));assertTrue(annotations.contains("0.00\t-0.00\t0.23\t-0.02"));assertTrue(annotations.contains("MISSING_SCORES_UNASSESSABLE"));assertTrue(annotations.contains("NONFINITE_SCORES_UNASSESSABLE"));assertEquals(false,read(root.resolve("analysis-status.json")).get("prediction_model_executed"));Files.delete(temporary.resolve("annotated.vcf"));assertEquals(0,run("--verify",root.toString()));}
    @Test void changedDerivedResultCannotBeResealedAsValid()throws Exception{assertEquals(0,execute(request()));Path root=temporary.resolve("result"),file=root.resolve("results/native/annotations.tsv");Files.writeString(file,Files.readString(file).replace("0.23","0.24"));SpliceAiToolsFiles.seal(root);assertEquals(2,run("--verify",root.toString()));}
    @Test void changedProducerOrPredictionClaimCannotBeResealed()throws Exception{assertEquals(0,execute(request()));Path root=temporary.resolve("result");var state=read(root.resolve("analysis-status.json"));state.put("prediction_model_executed",true);json(root.resolve("analysis-status.json"),state);SpliceAiToolsFiles.seal(root);assertEquals(2,run("--verify",root.toString()));}
    @Test void addedAnalysisOrResultMemberFailsEvenAfterResealing()throws Exception{assertEquals(0,execute(request()));Path root=temporary.resolve("result");Files.createDirectory(root.resolve("results/extra"));SpliceAiToolsFiles.seal(root);assertEquals(2,run("--verify",root.toString()));}
    @Test void missingInputIsSkipWithConcreteCauseAndAction()throws Exception{var r=request();r.put("annotated_vcf","absent.vcf");assertEquals(3,execute(r));String warning=Files.readString(temporary.resolve("result/WARNINGS.md"));assertTrue(warning.contains("SKIP3"));assertTrue(warning.contains("absent.vcf"));assertTrue(warning.contains("REQUIRED ACTION"));assertEquals(2,run("--verify",temporary.resolve("result").toString()));}
    @Test void literalInputIdentityChangeFailsWithNoAdmittedResult()throws Exception{var r=request();Files.writeString(temporary.resolve("original.vcf"),"##fileformat=VCFv4.2\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\n1\t8\tdifferent\tA\tC,G\t.\t.\t.\n");r.put("original_vcf","original.vcf");assertEquals(2,execute(r));assertEquals(false,read(temporary.resolve("result/analysis-status.json")).get("results_admitted"));}
    @Test void capacitiesFailWithoutTruncatedSuccessAndOutputIsPreserved()throws Exception{var r=request();r.put("maximum_annotations",1);assertEquals(2,execute(r));r.put("out","result2");r.put("maximum_annotations",10);r.put("maximum_output_bytes",10);assertEquals(2,execute(r));assertEquals(2,execute(r));assertTrue(Files.exists(temporary.resolve("result2/failure-stack.txt")));}
    @Test void unknownUnusedAndEditionChangesAreRejected()throws Exception{var r=request();r.put("threads",1);assertThrows(IOException.class,()->SpliceAiToolsRequest.validate(r));r.remove("threads");r.put("arbitrary_code","print(1)");assertThrows(IOException.class,()->SpliceAiToolsRequest.validate(r));}
    private Map<String,Object> original(){var r=new LinkedHashMap<String,Object>();r.putAll(Map.of("schema_version",1,"mode","RUN","backend","ORIGINAL","out","out","profile",SpliceAiToolsRequest.PROFILE,"input_vcf","all.vcf","runtime","/missing/runtime","reference",Map.of("fasta","full.fa","fai","full.fa.fai","fasta_sha256","a".repeat(64),"fai_sha256","b".repeat(64),"assembly","GRCh37"),"annotation",Map.of("kind","bundled-GENCODE24lift37"),"analyses",List.of(Map.of("id","full","distance",50,"mask",0))));return r;}
    @Test void originalDistanceIsExplicitAndNeverClampedOrEditionSubstituted()throws Exception{var r=original();assertEquals(50L,object(list(SpliceAiToolsRequest.validate(r).get("analyses"),"a").get(0),"a").get("distance"));r.put("analyses",List.of(Map.of("id","full","distance",5000,"mask",0)));assertThrows(SpliceAiToolsRuntime.Unavailable.class,()->SpliceAiToolsRequest.validate(r));r.put("analyses",List.of(Map.of("id","full","mask",0)));assertThrows(IOException.class,()->SpliceAiToolsRequest.validate(r));var supplied=original();supplied.put("profile","original-SpliceAI1.3.1");assertThrows(SpliceAiToolsRuntime.Unavailable.class,()->SpliceAiToolsRequest.validate(supplied));}
    @Test void bundleAssemblyMismatchIsNotRepaired()throws Exception{var r=original();r.put("annotation",Map.of("kind","bundled-GENCODE24"));assertThrows(IOException.class,()->SpliceAiToolsRequest.validate(r));}
    @Test void originalSourcePrefixBehaviorIsExactPythonStripNotGenericAlias(){assertEquals("1",SpliceAiToolsInputs.sourceChromosome("chr1chr","1"));assertEquals("chr1",SpliceAiToolsInputs.sourceChromosome("1","chr2"));assertEquals("MT",SpliceAiToolsInputs.sourceChromosome("MT","1"));assertEquals("chrM",SpliceAiToolsInputs.sourceChromosome("chrM","chr1"));}
    @Test void fullReferenceCheckRejectsWrongRefAndUnsupportedAlleles()throws Exception{Path fa=temporary.resolve("genome.fa"),fai=temporary.resolve("genome.fa.fai"),input=temporary.resolve("in.vcf");Files.writeString(fa,">chr1\nAACCGGTT\n");FastaIndexes.build(fa).write(fai);var r=SpliceAiToolsRequest.validate(original());String header="##fileformat=VCFv4.2\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\n";Files.writeString(input,header+"1\t3\tid\tC\tG\t.\t.\t.\n");assertEquals(1L,SpliceAiToolsInputs.inspect(input,fa,fai,temporary.resolve("good.tsv"),r).get("variants"));Files.writeString(input,header+"1\t3\tid\tA\tG\t.\t.\t.\n");assertThrows(IOException.class,()->SpliceAiToolsInputs.inspect(input,fa,fai,temporary.resolve("bad.tsv"),r));Files.writeString(input,header+"1\t3\tid\tC\t*\t.\t.\t.\n");assertThrows(SpliceAiToolsRuntime.Unavailable.class,()->SpliceAiToolsInputs.inspect(input,fa,fai,temporary.resolve("star.tsv"),r));}
    @Test void completeGeneTableKeepsDuplicateContextsAndRejectsSilentExonLoss()throws Exception{Path a=temporary.resolve("anno.tsv");String h="#NAME\tCHROM\tSTRAND\tTX_START\tTX_END\tEXON_START\tEXON_END\n";var r=SpliceAiToolsRequest.validate(original());Files.writeString(a,h+"gene.1\t1\t+\t0\t100\t0,80,\t20,100,\ngene.1\t1\t-\t0\t100\t0,\t100,\n");assertEquals(2L,SpliceAiToolsInputs.validateAnnotation(a,r).get("gene_context_rows"));Files.writeString(a,h+"gene.1\t1\t+\t0\t100\t0,80\t20,100\n");assertThrows(IOException.class,()->SpliceAiToolsInputs.validateAnnotation(a,r));}
}
